<?php use Luna\Core\Csrf;use Luna\Core\View;$token=View::e(Csrf::token());?>
<div class="page-intro"><div><span class="eyebrow">Fleet & service</span><h1>Noleggio e assistenza</h1><p>Canoni ricorrenti, chilometraggi, rinnovi, ticket e SLA automatizzati.</p></div><div class="intro-actions"><a class="button" href="/r/rental-contracts/create">Nuovo contratto</a><a class="button" href="/r/rental-tickets/create">Nuovo ticket</a><form method="post" action="/operations/rental/automate"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Esegui automazioni</button></form></div></div>
<section class="accounting-kpis"><article><span>Contratti attivi</span><strong><?= count(array_filter($contracts,fn($c)=>$c['status']==='ACTIVE')) ?></strong></article><article><span>Ticket aperti</span><strong><?= count(array_filter($tickets,fn($t)=>!in_array($t['status'],['RESOLVED','CLOSED'],true))) ?></strong></article><article><span>SLA superati</span><strong><?= count(array_filter($tickets,fn($t)=>(bool)$t['sla_breached'])) ?></strong></article><article><span>Scadenze aperte</span><strong><?= count($deadlines) ?></strong></article></section>
<section class="card"><div class="card-header"><h2>Contratti</h2></div><div class="table-wrap"><table><thead><tr><th>Contratto</th><th>Cliente</th><th>Veicolo</th><th>Fine</th><th>Canone</th><th>Km</th><th>Prossima fattura</th><th>Rilevazione</th></tr></thead><tbody><?php foreach($contracts as $c):?><tr><td class="primary-cell"><?= View::e($c['contract_number']) ?></td><td><?= View::e($c['customer_name']) ?></td><td><?= View::e($c['vehicle_plate']??'—') ?></td><td><?= View::date($c['end_date']) ?></td><td><?= View::money($c['monthly_fee']) ?></td><td><?= number_format((int)$c['current_km'],0,',','.') ?></td><td><?= View::date($c['next_invoice_date']??null) ?></td><td><form method="post" action="/operations/rental/contracts/<?= (int)$c['id'] ?>/meter" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="date" name="reading_date" value="<?= date('Y-m-d') ?>"><input type="number" name="kilometers" min="<?= (int)$c['current_km'] ?>" placeholder="km" required><button class="button">Registra</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Ticket e SLA</h2></div><div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Cliente</th><th>Oggetto</th><th>Priorità</th><th>SLA</th><th>Stato</th><th>Assegnazione</th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td class="primary-cell"><?= View::e($t['ticket_number']) ?></td><td><?= View::e($t['customer_name']) ?></td><td><?= View::e($t['subject']) ?></td><td><?= View::e($t['priority']) ?></td><td class="<?= $t['sla_breached']?'danger-text':'' ?>"><?= View::date($t['sla_due_at']) ?></td><td><span class="badge status-<?= strtolower($t['status']) ?>"><?= View::e($t['status']) ?></span></td><td><form method="post" action="/operations/rental/tickets/<?= (int)$t['id'] ?>/status" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><select name="status"><?php foreach(['OPEN','IN_PROGRESS','WAITING','RESOLVED','CLOSED'] as $s):?><option <?= $s===$t['status']?'selected':'' ?>><?= $s ?></option><?php endforeach;?></select><select name="assigned_to"><option value="">—</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>" <?= (int)$u['id']===(int)($t['assigned_to']??0)?'selected':'' ?>><?= View::e($u['name']) ?></option><?php endforeach;?></select><button class="button">Aggiorna</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Scadenze operative</h2></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Contratto</th><th>Tipo</th><th>Descrizione</th><th>Stato</th></tr></thead><tbody><?php foreach($deadlines as $d):?><tr><td><?= View::date($d['due_date']) ?></td><td><?= View::e($d['contract_number']??'—') ?></td><td><?= View::e($d['deadline_type']) ?></td><td class="primary-cell"><?= View::e($d['description']) ?></td><td><span class="badge status-<?= strtolower($d['status']) ?>"><?= View::e($d['status']) ?></span></td></tr><?php endforeach;?></tbody></table></div></section>
